/bin/bash -lc "npm test && node --input-type=module - <<'EOF'
import assert from 'node:assert/strict';
import { createSchedule, listSchedules, runDueSchedules, deleteSchedule } from './src/server.js';
const s = createSchedule({accountId:'a', recipient:'x@example.com', frequency:'daily', format:'json'}, new Date('2026-01-01T00:00:00Z'));
assert.equal(listSchedules('a').length, 1);
const out = await runDueSchedules(new Date('2026-01-02T00:00:00Z'), async d => assert.match(d.body, /login/));
assert.equal(out.length, 1); assert.equal(deleteSchedule(s.id), true);
console.log('schedule smoke test passed');
EOF"

